using YMusicTaskbar;

int count = 0;
void Check(bool value, string name) { if (!value) throw new Exception(name); Console.WriteLine("PASS " + name); count++; }
Check(Policy.FindGap(0, 2560, 540, new[] { new Span(0, 180), new Span(900, 1700), new Span(2150, 2560) }) == 188, "Place after widgets, before centered icons");
Check(Policy.FindGap(-2560, 0, 540, new[] { new Span(-2560, -2380), new Span(-1660, -860), new Span(-410, 0) }) == -2372, "Negative monitor coordinates");
Check(Policy.FindGap(0, 1000, 400, new[] { new Span(0, 500), new Span(400, 900) }) is null, "No overlap when occupied spans intersect");
Check(Policy.FindGap(0, 1000, 400, new[] { new Span(200, 800) }) is null, "Hide when no contiguous space");
Check(Policy.FindGap(0, 600, 580, Array.Empty<Span>()) == 8, "Keep edge padding");
Check(Policy.FindGap(0, 600, 590, Array.Empty<Span>()) is null, "Reject panel wider than available space");
Check(Policy.FindGap(0, 1000, 200, new[] { new Span(-200, 100), new Span(800, 1200) }) == 108, "Clip occupancy extending beyond taskbar");
var primary = new MonitorOption("primary", true, false, true, true);
var secondary = new MonitorOption("secondary", false, false, true, true);
Check(Policy.ChooseMonitor(new[] { secondary, primary }) == "primary", "Prefer selected screen");
Check(Policy.ChooseMonitor(new[] { primary with { Fullscreen = true }, secondary }) == "secondary", "Move away from fullscreen");
Check(Policy.ChooseMonitor(new[] { primary with { Fullscreen = true }, secondary with { Fullscreen = true } }) is null, "Hide when both screens fullscreen");
Check(Policy.ChooseMonitor(new[] { primary with { TaskbarVisible = false }, secondary }) == "secondary", "Avoid hidden taskbar");
Check(Policy.ChooseMonitor(new[] { primary with { HasRoom = false }, secondary }) == "secondary", "Avoid crowded taskbar");
Check(Policy.PositionSeconds(5, 2, true, 100) == 7, "Extrapolate playing timeline");
Check(Policy.PositionSeconds(5, 2, false, 100) == 5, "Pause freezes progress");
Check(Policy.PositionSeconds(99, 10, true, 100) == 100, "Clamp to track end");
Check(Policy.PositionSeconds(5, -10, true, 100) == 5, "Ignore future timestamp");
Check(Policy.PositionSeconds(5, 2, true, 0) == 0, "Handle missing duration");
Console.WriteLine($"{count} checks passed");
Check(Policy.ValueAtX(5, 100, 200) == 0, "Scrubber left edge");
Check(Policy.ValueAtX(95, 100, 200) == 200, "Scrubber right edge");
Check(Policy.ValueAtX(50, 100, 200) == 100, "Scrubber middle");
Check(Policy.ValueAtX(-10, 100, 200) == 0, "Drag before start clamps");
Check(Policy.ValueAtX(500, 100, 200) == 200, "Drag past end clamps");
Check(Policy.ValueAtX(5, 0, 0) == 0, "Empty scrubber is safe");
Console.WriteLine($"Total: {count} checks passed");
var now = DateTimeOffset.UtcNow;
var seek = new SeekPreview();
seek.Begin(60, now);
Check(seek.Display(10, true, 100, now.AddMilliseconds(200)) == 60.2, "Stale seek reply never moves thumb back");
Check(seek.Display(60.5, true, 100, now.AddMilliseconds(500)) == 60.5, "Confirmed seek resumes real timeline");
Check(seek.Display(62, true, 100, now.AddSeconds(2)) == 62, "Confirmed position remains authoritative");
seek.Begin(60, now);
Check(seek.Display(10, false, 100, now.AddSeconds(1)) == 60, "Pending paused seek stays at target");
Check(seek.Display(10, false, 100, now.AddSeconds(3)) == 10, "Unconfirmed seek eventually uses real state");
seek.Begin(60, now); seek.Cancel();
Check(seek.Display(10, false, 100, now) == 10, "Rejected command cancels preview");
Console.WriteLine($"Final: {count} checks passed");
var primarySlot = new DesktopSlot("main", true, new(0, 0, 2560, 1440), new(0, 1386, 2560, 1440), false, true,
    new[] { new Span(0, 180), new Span(900, 1700), new Span(2150, 2560) }, null);
var otherSlot = primarySlot with { Monitor = "other", Primary = false };
Check(PlacementPlanner.Choose(new[] { primarySlot, otherSlot }, "main")?.X == 188, "Production planner uses free taskbar gap");
Check(PlacementPlanner.Choose(new[] { primarySlot with { Fullscreen = true }, otherSlot }, "main")?.Monitor == "other", "Production planner transfers monitor");
Check(PlacementPlanner.Choose(new[] { primarySlot with { Fullscreen = true }, otherSlot with { Fullscreen = true } }, "main") is null, "Production planner hides when all fullscreen");
var compactPlacement = PlacementPlanner.Choose(new[] { primarySlot }, "main", true, 310);
Check(compactPlacement is { Width: 310, Height: 32 }, "Production planner preserves compact dimensions");
var hidpi = primarySlot with { Dpi = 192, Taskbar = new(0, 1344, 2560, 1440), Occupied = Array.Empty<Span>() };
Check(PlacementPlanner.Choose(new[] { hidpi }, "main") is { Width: 1080, Height: 92 }, "Production planner scales physical pixels once");
var cache = new DesktopSnapshotCache();
cache.Merge(new[] { primarySlot }, now);
var failed = primarySlot with { Visible = false, Occupied = Array.Empty<Span>(), Error = "transient", Fullscreen = true };
var held = cache.Merge(new[] { failed }, now.AddSeconds(1))[0];
Check(held.Visible && held.Occupied.Count > 0 && held.Fullscreen, "Accessibility grace preserves fresh fullscreen state");
Check(!cache.Merge(new[] { failed }, now.AddSeconds(4))[0].Visible, "Accessibility grace expires");
Check(!cache.Merge(new[] { primarySlot with { Visible = false } }, now.AddSeconds(1))[0].Visible, "Real taskbar hiding is immediate");
Check(SeekTarget.Normalize(0, 200) == 0.1, "Restart avoids ignored zero media command");
Check(SeekTarget.Normalize(200, 200) == 199.5, "End seek avoids end-of-track transition boundary");
Check(SeekTarget.Normalize(-10, 200) == 0.1, "Seek before start uses safe beginning");
Check(SeekTarget.Normalize(300, 200) == 199.5, "Seek after end stays inside track");
Check(SeekTarget.Normalize(75, 200) == 75, "Interior seek is unchanged");
Check(SeekTarget.Normalize(0, 0.1) == 0.025 && Math.Abs(SeekTarget.Normalize(0.1, 0.1)!.Value - 0.075) < 0.000001, "Subsecond tracks retain ordered seek bounds");
Check(SeekTarget.Normalize(1, 0) is null && SeekTarget.Normalize(1, -1) is null, "Unknown duration cannot dispatch seek");
Check(SeekTarget.Normalize(double.NaN, 200) is null && SeekTarget.Normalize(double.PositiveInfinity, 200) is null && SeekTarget.Normalize(1, double.NaN) is null, "Nonfinite seek data is rejected");
seek.Begin(SeekTarget.Normalize(0, 200)!.Value, now);
Check(seek.Display(80, false, 200, now) == 0.1, "Seek preview uses actual normalized command target");
Check(seek.Display(80, false, 200, now.AddSeconds(3)) == 80, "Ignored restart cannot leave a false beginning displayed");
var windows10 = primarySlot with { Bounds = new(0, 0, 1920, 1080), Taskbar = new(0, 1040, 1920, 1080),
    Occupied = new[] { new Span(0, 680), new Span(1650, 1920) } };
Check(PlacementPlanner.Choose(new[] { windows10 }, null) is { X: 688, Y: 1042, Height: 36 }, "Windows 10 bottom taskbar places full player between apps and tray");
Check(PlacementPlanner.Choose(new[] { windows10 with { Taskbar = new(0, 0, 1920, 40) } }, null) is { Y: 2 }, "Windows 10 top taskbar keeps player inside its bounds");
var smallButtons = windows10 with { Taskbar = new(0, 1050, 1920, 1080) };
Check(PlacementPlanner.Choose(new[] { smallButtons }, null, true) is { Height: 26 }, "Small Windows 10 taskbar supports compact player");
Check(PlacementPlanner.Choose(new[] { smallButtons }, null) is null, "Small taskbar hides full layout when it cannot fit");
Check(PlacementPlanner.Choose(new[] { windows10 with { Taskbar = new(0, 0, 64, 1080) } }, null) is null, "Vertical taskbar never receives a horizontal overlay");
Check(TaskbarRegions.IsReservedShellControl("TrayNotifyWnd") && TaskbarRegions.IsReservedShellControl("SearchEditBoxWrapperClass"), "Windows 10 notification and search windows are reserved");
Check(!TaskbarRegions.IsReservedShellControl("ReBarWindow32") && !TaskbarRegions.IsReservedShellControl("MSTaskListWClass"), "Task-list containers do not consume the whole free gap");
Check(TaskbarRegions.Intersect(windows10.Taskbar, new(1640, 1040, 2000, 1080)) is { Start: 1640, End: 1920 }, "Native tray bounds are clipped to the taskbar");
Check(TaskbarRegions.Intersect(windows10.Taskbar, new(0, 0, 1920, 40)) is null, "Unrelated native windows do not reserve taskbar space");
var scaledWindows10 = windows10 with { Dpi = 144, Taskbar = new(0, 1020, 1920, 1080) };
Check(PlacementPlanner.Choose(new[] { scaledWindows10 }, null) is { Height: 56, Dpi: 144 }, "Windows 10 taskbar preserves physical DPI coordinates");
var profiles = new Settings { PreferredMonitor = windows10.Monitor };
profiles.Monitors[windows10.Monitor] = new MonitorProfile { Side = PlayerSide.Right, Compact = true };
var rightCompact = PlacementPlanner.ChooseForSettings(new[] { windows10 }, profiles);
Check(rightCompact is { Height: 32 } && rightCompact.X + rightCompact.Width == 1642, "Monitor profile anchors compact player to right free edge");
profiles.Monitors[windows10.Monitor].Compact = false;
Check(PlacementPlanner.ChooseForSettings(new[] { windows10 }, profiles) is { Height: 36, X: 1102 }, "Profile full mode uses its own height and right anchor");
profiles.Monitors[windows10.Monitor].Side = PlayerSide.Left;
Check(PlacementPlanner.ChooseForSettings(new[] { windows10 }, profiles) is { X: 688 }, "Left profile anchors after application buttons");
var crowded = windows10 with { Occupied = new[] { new Span(0, 1100), new Span(1650, 1920) } };
Check(PlacementPlanner.ChooseForSettings(new[] { crowded }, profiles) is { X: 1108, Width: 480 }, "New app buttons move and shrink player without overlap");
Check(PlacementPlanner.ChooseForSettings(new[] { crowded with { Occupied = new[] { new Span(0, 1500), new Span(1650, 1920) } } }, profiles) is null, "Player hides when additional buttons leave no usable gap");
var other = windows10 with { Monitor = "other", Primary = false };
profiles.Monitors["other"] = new MonitorProfile { Compact = true, Side = PlayerSide.Right };
Check(PlacementPlanner.ChooseForSettings(new[] { windows10 with { Fullscreen = true }, other }, profiles) is { Monitor: "other", Height: 32 }, "Fullscreen fallback applies destination monitor profile");
profiles.Monitors["other"].Enabled = false;
Check(PlacementPlanner.ChooseForSettings(new[] { windows10 with { Fullscreen = true }, other }, profiles) is null, "Disabled monitor is never used as fallback");
Check(new Settings { Compact = true }.ProfileFor("new monitor").Compact, "Legacy settings provide a default profile for new displays");
Check(Policy.FindGap(0, 1000, 200, new[] { new Span(300, 700) }, 8, PlayerSide.Right) == 792, "Right alignment selects the last available gap");
Console.WriteLine($"{count} core checks passed");
